}
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}
"use server";

/**
 * Soft-deletes a comment.
 *
 * Owner D. Deletion is a soft delete: `CommentService` stamps `archived_at`
 * through `archivePatch()` and the thread query filters it out, so replies
 * hanging off the comment keep their parent id.
 *
 * Must call (do not reimplement): deleteCommentSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { deleteCommentSchema, type DeleteCommentInput } from "@/schemas/comment";
import { deleteComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof deleteCommentSchema, Comment>(
  deleteCommentSchema,
  async (raw, actor) => {
    const input = raw as DeleteCommentInput;

    const allowed = can(actor, "comment:delete", {
      kind: "comment",
      orgId: input.orgId,
      commentId: input.commentId,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:delete");
    }

    const comment = await deleteComment(actor, input);
    revalidateTagged([issueTag(comment.issueId)], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function deleteCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}
"use server";

/**
 * Archives an issue (soft delete).
 *
 * Owner D. `assertNotArchived()` makes the operation fail loudly rather than
 * silently re-stamping `archived_at`, which would otherwise reset the retention
 * clock the cleanup job reads.
 *
 * Must call (do not reimplement): archiveIssueSchema, can, assertNotArchived,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { archiveIssueSchema } from "@/schemas/issue";
import { archiveIssue, getIssue } from "@/server/services/issue-service";
import type { ActionResult } from "@/types/api";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";

type ArchiveIssueInput = { orgId: OrgId; issueId: IssueId };

const run = withAction<typeof archiveIssueSchema, Issue>(
  archiveIssueSchema,
  async (raw, actor) => {
    const input = raw as ArchiveIssueInput;

    const current = await getIssue(actor, input.orgId, input.issueId);

    const allowed = can(actor, "issue:archive", {
      kind: "issue",
      orgId: input.orgId,
      projectId: current.issue.projectId,
      issueId: input.issueId,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:archive");
    }

    assertNotArchived("issue", input.issueId, current.issue);

    const issue = await archiveIssue(actor, input.orgId, input.issueId);
    revalidateTagged(
      [issueTag(issue.id), projectTag(issue.projectId)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues", "board"], cacheProfile: "minutes" },
);

export async function archiveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}

