/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import { isLive } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks every page of a keyset-paginated listing, so a tenant with more rows
 * than one page (oldest rows included) is still covered in full.
 */
async function forEachPage<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await fetchPage(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Stale documents (deleted comments, archived issues) are cleared
 * first so the index ends up holding exactly the live content. Scoped to a
 * single org on purpose: a full-fleet reindex is a sequence of these, so one
 * slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteAllSearchDocuments(orgId);

    await forEachPage(
      (cursor) =>
        projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    // Archived issues are not indexed: their search documents were removed
    // on archive and must not come back on rebuild.
    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({ orgId, limit: PAGE_SIZE, cursor }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          // The thread walk returns every comment in reading order, replies
          // included. Deleted comments are skipped, but a live reply under a
          // deleted parent is still indexed.
          const thread = await commentRepo.listThread(orgId, issue.id);
          const comments = thread.flatMap((node) => [
            node.comment,
            ...node.replies,
          ]);

          for (const comment of comments) {
            if (!isLive(comment)) continue;
            await indexComment(orgId, comment);
            result.processed += 1;
          }
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );
  });
}

